// Translate the Directory lookup into { exists: bool }.
// 200 with an id/primaryEmail => the account exists.
// 404 / error (continueOnFail) => it does not.
const webhook = $('Verify Workspace Webhook').first().json;
const body = webhook.body || webhook.query || {};
const workEmail = String(body.work_email || '').trim().toLowerCase();

const r = $json || {};
const exists = !r.error && !!(r.id || r.primaryEmail);

return [{
  json: {
    ok: true,
    exists,
    work_email: workEmail,
    primaryEmail: r.primaryEmail || null,
    suspended: typeof r.suspended === 'boolean' ? r.suspended : null
  }
}];
